18	/**
19	 * CLI entry point for TreeGuard.
20	 */
21	final class Application
22	{
23	    private const VERSION = '1.0.0';
24	
25	    /** @readonly */
26	    private TreeGuardOutputWriter $writer;
27	
28	    /** @readonly */
29	    private TreeGuardCliArgumentParser $argumentParser;
30	
