42	
43	    /** @readonly */
44	    private ReporterFactory $reporterFactory;
45	
46	    /**
47	     * Creates the TreeGuard CLI application for a project working directory.
48	     */
49	    public function __construct(
50	        /** @readonly */
51	        private string $workingDirectory,
52	        ?ConfigLoader $configLoader = null,
53	        ?TreeGuardAnalyzer $analyzer = null,
54	        ?ReporterFactory $reporterFactory = null,
55	        ?Closure $stdout = null,
56	        ?Closure $stderr = null,
57	        ?TreeGuardCliArgumentParser $argumentParser = null,
58	        ?TreeGuardHelpText $helpText = null,
59	        ?TreeGuardAnalysisRunner $analysisRunner = null,
60	    ) {
61	        $this->configLoader = $configLoader ?? new ConfigLoader();
62	        $this->analyzer = $analyzer ?? new TreeGuardAnalyzer();
63	        $this->reporterFactory = $reporterFactory ?? new ReporterFactory();
64	        $this->writer = new TreeGuardOutputWriter($stdout, $stderr);
65	        $this->argumentParser = $argumentParser ?? new TreeGuardCliArgumentParser();
66	        $this->helpText = $helpText ?? new TreeGuardHelpText();
67	        $this->analysisRunner = $analysisRunner ?? new TreeGuardAnalysisRunner(
68	            $this->workingDirectory,
69	            $this->configLoader,
70	            $this->analyzer,
71	            $this->reporterFactory,
72	            $this->writer,
73	        );
74	    }
75	
76	    /**
77	     * @param list<string> $argv
78	     */
79	    public function run(array $argv): int
80	    {
81	        array_shift($argv);
82	        try {
83	            $arguments = $this->argumentParser->parse($argv);
84	        } catch (TreeGuardException $exception) {
85	            $this->writer->writeError(sprintf("TreeGuard error: %s\n", $exception->getMessage()));
86	
87	            return 2;
88	        }
89	
90	        if ($arguments['help']) {
91	            $this->writer->write($this->helpText->text());
92	
93	            return 0;
94	        }
95	
96	        if ($arguments['version']) {
97	            $this->writer->write(sprintf("tree-guard %s\n", self::VERSION));
98	
99	            return 0;
100	        }
101	
102	        return $this->analysisRunner->run($arguments['config'], $arguments['reporter']);
103	    }
104	}
