20	{
21	    /** @readonly */
22	    private ConfigStringListReader $stringListReader;
23	
24	    /** @readonly */
25	    private RuleListConfigReader $ruleListConfigReader;
26	
27	    /** @readonly */
28	    private ReportConfigReader $reportConfigReader;
29	
30	    /**
31	     * Creates a config loader from YAML section readers.
32	     */
33	    public function __construct(
34	        ?ConfigStringListReader $stringListReader = null,
35	        ?RuleListConfigReader $ruleListConfigReader = null,
36	        ?ReportConfigReader $reportConfigReader = null,
37	    ) {
38	        $this->stringListReader = $stringListReader ?? new ConfigStringListReader();
39	        $this->ruleListConfigReader = $ruleListConfigReader ?? new RuleListConfigReader();
40	        $this->reportConfigReader = $reportConfigReader ?? new ReportConfigReader();
41	    }
42	
43	    /**
44	     * Loads and validates a TreeGuard YAML configuration file.
45	     *
46	     * @throws TreeGuardException when the file is missing, unparsable, or not a mapping
47	     */
48	    public function load(string $path): TreeGuardConfig
49	    {
50	        if (!is_file($path)) {
51	            throw new TreeGuardException(sprintf('TreeGuard config not found: %s', $path));
52	        }
53	
54	        try {
55	            $data = Yaml::parseFile($path);
56	        } catch (ParseException $exception) {
57	            throw new TreeGuardException('Invalid tree.yaml: ' . $exception->getMessage(), 0, $exception);
58	        }
59	
60	        if (!is_array($data)) {
61	            throw new TreeGuardException('Invalid tree.yaml: top-level value must be a mapping.');
62	        }
63	
64	        return new TreeGuardConfig(
65	            dirname($path),
66	            $this->stringListReader->read($data, 'paths', ['src'], ''),
67	            $this->stringListReader->read($data, 'exclude', [], ''),
68	            $this->ruleListConfigReader->read($data['rules'] ?? []),
69	            $this->reportConfigReader->read($data['report'] ?? []),
70	        );
71	    }
72	}
