16	final class ViolationFieldComparator
17	{
18	    /**
19	     * Returns comparison result for the selected field.
20	     */
21	    public function compare(Violation $left, Violation $right, string $field): int
22	    {
23	        if ($field === 'path') {
24	            return strcmp($left->path, $right->path);
25	        }
26	
27	        if ($field === 'rule') {
28	            return strcmp($left->rule, $right->rule);
29	        }
30	
31	        if ($field === 'actual') {
32	            return $this->compareNullableInt($left->actual, $right->actual);
33	        }
34	
35	        return $this->compareNullableInt($left->limit, $right->limit);
36	    }
37	
38	    /**
39	     * Returns comparison result for nullable integers with null ordered first.
40	     */
41	    public function compareNullableInt(?int $left, ?int $right): int
42	    {
43	        if ($left === null && $right === null) {
44	            return 0;
45	        }
46	
47	        if ($left === null) {
48	            return -1;
49	        }
50	
51	        if ($right === null) {
52	            return 1;
53	        }
54	
55	        return $left <=> $right;
56	    }
57	}
