66	        $this->analyzer = $analyzer ?? new LocGuardAnalyzer();
67	        $this->reporterFactory = $reporterFactory ?? new ReporterFactory();
68	        $this->writer = new LocGuardOutputWriter($stdout, $stderr);
69	        $this->argumentParser = $argumentParser ?? new LocGuardCliArgumentParser();
70	        $this->helpText = $helpText ?? new LocGuardHelpText();
71	        $this->analysisRunner = $analysisRunner ?? new LocGuardAnalysisRunner(
72	            $this->workingDirectory,
73	            $this->configLoader,
74	            $this->analyzer,
75	            $this->reporterFactory,
76	            $this->writer,
77	        );
78	        $this->explainRunner = $explainRunner ?? new LocGuardExplainRunner(
79	            $this->workingDirectory,
80	            $this->configLoader,
81	            $this->writer,
82	        );
83	    }
84	
85	    /**
86	     * @param list<string> $argv
87	     */
88	    public function run(array $argv): int
89	    {
90	        array_shift($argv);
91	        try {
92	            $arguments = $this->argumentParser->parse($argv);
93	        } catch (LocGuardException $exception) {
94	            $this->writer->writeError(sprintf("LocGuard error: %s\n", $exception->getMessage()));
95	
96	            return 2;
97	        }
98	
99	        if ($arguments['help']) {
100	            $this->writer->write($this->helpText->text());
101	
102	            return 0;
